template <typename T>
struct RestoreOperationValue {
    T& value;
    T previous;
    explicit RestoreOperationValue(T& target) : value(target), previous(target) {}
    ~RestoreOperationValue() { value = previous; }
};

String current_exception_message()
{
    const auto active = ::cw::lib::capture_exception();
    if (!active) return "no active exception";
    bool waited = false;
    try {
        ::cw::lib::rethrow_exception(active);
    } catch (const ::cw::event::EffectBreakError&) {
        return "EffectBreakError";
    } catch (const ::cw::event::XmlContentCriticalError& error) {
        return error.m_msg.empty() ? "XmlContentCriticalError" : error.m_msg;
    } catch (const std::exception& error) {
        return error.what();
    } catch (...) {
        return "unknown exception";
    }
}

template <typename T>
std::shared_ptr<T> object_value(const Value& value)
{
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
    return object ? std::dynamic_pointer_cast<T>(*object) : nullptr;
}

