void CWPy::force_exec_func_11(::cw::lib::Callback arg_func, const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    if (!arg_func) return;
    arg_func = ::cw::dialog::retain_current_dialog_input(std::move(arg_func));
    std::scoped_lock lock(m_game_exec_mutex);
    // Py と同様、通常・FORCE_USEREVENT のコールバックは
    // 同じ先入れ先出し順に送る。 強制指定は入力専用待機中の実行を許すだけ
    // で、通常のイベント処理中に先行する通常コールバックを追い越さない。
    m_game_exec_queue.push_back({std::move(arg_func), arg_args, arg_kwargs, nullptr, true});
}

