bool CWPy::is_gameover()
{
    if (is_playingscenario() && !m__forcegameover) {
        m__gameover = true;
        const auto pcards = get_pcards(Value("unreversed"));
        for (const auto& pcard : pcards) {
            if (pcard && pcard->is_alive()) {
                m__gameover = false;
                break;
            }
        }
        if (pcards.empty()) m__gameover = true;
    }
    return m__gameover;
}

