void StoredParty::initialize(std::shared_ptr<::cw::data::Party> arg_party)
{
    if (!arg_party) return;
    auto members = std::make_shared<::cw::data::VariantSequence>();
    members->m_values = arg_party->m_members;
    m_members = std::static_pointer_cast<::cw::lib::Object>(members);
    auto backpack = std::make_shared<::cw::data::VariantSequence>();
    for (const auto& header : arg_party->m_backpack) {
        if (header) backpack->m_values.emplace_back(std::static_pointer_cast<::cw::lib::Object>(header));
    }
    std::stable_sort(backpack->m_values.begin(), backpack->m_values.end(), [](const Value& lhs, const Value& rhs) {
        return value_integer(object_value<::cw::header::CardHeader>(lhs) ?
                                 object_value<::cw::header::CardHeader>(lhs)->m_order : Value{}, 0) <
               value_integer(object_value<::cw::header::CardHeader>(rhs) ?
                                 object_value<::cw::header::CardHeader>(rhs)->m_order : Value{}, 0);
    });
    m_backpack = std::static_pointer_cast<::cw::lib::Object>(backpack);
    // PythonのStoredParty.__init__は常に空のfpathで開始する。
    m_fpath.clear();
    m_is_suspendlevelup = Value(arg_party->m_is_suspendlevelup);
    m_money = Value(arg_party->m_money);
    m_name = Value(arg_party->m_name);
}

