void post_pygameevent(std::shared_ptr<::cw::lib::Object> arg_event)
{
    if (!arg_event || !::cw::g_cwpy) return;
    std::scoped_lock lock(::cw::g_cwpy->m_events_mutex);
    try {
        const auto input = std::dynamic_pointer_cast<::cw::eventhandler::InputEvent>(arg_event);
        if (::cw::g_cwpy->m_action_pointer_events &&
            !(::cw::g_cwpy->m_interrupt_eventhandler && *::cw::g_cwpy->m_interrupt_eventhandler) && input &&
            (input->type == ::cw::eventhandler::EVENT_POINTERCANCEL ||
             ((input->button == 1 || input->button == 3) &&
              (input->type == ::cw::eventhandler::EVENT_MOUSEBUTTONDOWN ||
               input->type == ::cw::eventhandler::EVENT_MOUSEBUTTONUP)))) {
            ::cw::g_cwpy->m_action_pointer_events->push_back(arg_event);
            // CANCELでは通常の入力処理側も初期化する。ボタンの押下・解放の
            // 変化は実行中のアクションだけが扱い、カードのクリックには渡さない。
            if (input->type != ::cw::eventhandler::EVENT_POINTERCANCEL) return;
        }
        ::cw::g_cwpy->m_parked_pygame_events.push_back(std::move(arg_event));
    } catch (const std::exception&) {
        // Pythonはキューのあふれ時に待機中の入力を消去し、このイベントを再試
        // 行する。ネイティブ版のpush_backはメモリ確保に失敗し得るため、
        // ここでは同じ確保を繰り返さず、入力を消去して失敗した送信を破棄する。後
        // 続の送信元は新しいイベントを送れるが、このイベントを後回しにはしない。
        ::cw::g_cwpy->clear_inputevents();
    }
}

void main()
{
    // Frameの構築は実行ファイルやSDLホストが担う。ホストがグ
    // ローバルのCWPyを設定済みなら、Pythonモジュールの入
    // 口と同様にそのループを実行する。未設定の場合、このライブラリ
    // の翻訳単位ではウィンドウやバックエンドを安全に構築できない。
    if (::cw::g_cwpy && ::cw::g_cwpy->to_bool()) ::cw::g_cwpy->run();
}

